-- More exercises (idempotent). Applied with execute_sql, same as seed.sql.
insert into public.exercises
  (slug, name, category, muscle_group, kit, kind, muscles, rep_lo, rep_hi, weight_step_kg, default_increment_kg,
   setup, cues, mistakes, default_notes, backup_name, sort_order)
values
  ('seatedlegpress', 'Seated leg press', 'lower', 'Legs', 'Machine', 'weight', array['Quads', 'Glutes', 'Hamstrings'], 8, 12, 5, 5, array['Sit back in the seat with your back and hips flat against the pad.', 'Place your feet shoulder-width apart on the middle of the plate.', 'Set the seat so your knees start at about 90 degrees.'], array['Press through your whole foot, not your toes.', 'Lower under control until your knees reach 90 degrees.', 'Stop just short of locking your knees.'], array['Letting your hips curl up off the seat at the bottom.', 'Locking your knees hard at the top.', 'Letting your knees fall inwards.'], '', 'Leg press', 18),
  ('pecdeck', 'Pec deck fly', 'upper', 'Chest', 'Machine', 'weight', array['Chest', 'Front shoulders'], 8, 12, 2.5, 2.5, array['Set the seat so the handles sit at chest height.', 'Sit with your back flat against the pad.', 'Start with your arms open, elbows slightly bent.'], array['Bring the handles together in a wide hug.', 'Squeeze your chest for a beat at the middle.', 'Return slowly until you feel a stretch.'], array['Using your arms to pull instead of your chest.', 'Shrugging your shoulders up.', 'Letting the weights slam back.'], '', 'Cable fly', 19),
  ('cablefly', 'Cable fly', 'upper', 'Chest', 'Cable', 'weight', array['Chest', 'Front shoulders'], 8, 12, 2.5, 2.5, array['Set both pulleys at about shoulder height.', 'Stand in the middle with one foot slightly forward.', 'Hold a handle in each hand with a soft bend in your elbows.'], array['Bring your hands together in a hugging arc.', 'Keep your chest tall and ribs down.', 'Control the return until your chest stretches.'], array['Turning it into a press by bending your elbows.', 'Leaning your whole body into the pull.', 'Going so heavy your shoulders roll forward.'], '', 'Pec deck fly', 20),
  ('dbpress', 'Dumbbell bench press', 'upper', 'Chest', 'Dumbbells', 'weight', array['Chest', 'Shoulders', 'Triceps'], 8, 12, 2, 2, array['Sit on the bench with a dumbbell on each thigh, then lie back and kick them up.', 'Plant your feet and keep your shoulder blades pinched back.', 'Start with the dumbbells over your chest, palms facing forward.'], array['Lower until your elbows are just below the bench.', 'Press up and slightly in over your chest.', 'Keep your wrists straight over your elbows.'], array['Flaring your elbows out wide.', 'Bouncing the weights off your chest.', 'Lifting your hips off the bench.'], '', 'Chest press', 21),
  ('pushup', 'Push-up', 'upper', 'Chest', 'Bodyweight', 'bodyweight', array['Chest', 'Shoulders', 'Triceps'], 8, 15, 2.5, 2.5, array['Place your hands slightly wider than your shoulders.', 'Make a straight line from your head to your heels.', 'Brace your core and squeeze your glutes.'], array['Lower your chest to a fist''s height from the floor.', 'Keep your elbows at about 45 degrees from your body.', 'Press the floor away and keep your body in one line.'], array['Letting your hips sag or pike up.', 'Flaring your elbows straight out.', 'Only going halfway down.'], '', 'Knee push-up', 22),
  ('dbshoulder', 'Dumbbell shoulder press', 'upper', 'Shoulders', 'Dumbbells', 'weight', array['Shoulders', 'Triceps'], 8, 12, 2, 2, array['Sit on a bench with the back pad upright.', 'Hold the dumbbells at shoulder height, palms forward.', 'Brace your core and keep your ribs down.'], array['Press up until your arms are nearly straight.', 'Bring the weights together slightly at the top.', 'Lower under control to ear height.'], array['Arching your lower back.', 'Shrugging at the top.', 'Letting the dumbbells drift out wide.'], '', 'Shoulder press', 23),
  ('cablelateral', 'Cable lateral raise', 'upper', 'Shoulders', 'Cable', 'weight', array['Side shoulders'], 8, 12, 2.5, 2.5, array['Set the pulley low and stand side-on to the stack.', 'Hold the handle with the arm furthest from the stack.', 'Stand tall with a soft bend in your elbow.'], array['Raise your arm out to the side to shoulder height.', 'Lead with your elbow, not your hand.', 'Lower slowly so the cable stays tight.'], array['Swinging your body to lift.', 'Raising your hand above your elbow.', 'Shrugging your shoulder up.'], '', 'Lateral raise', 24),
  ('facepull', 'Face pull', 'upper', 'Shoulders', 'Cable', 'weight', array['Rear shoulders', 'Upper back'], 10, 15, 2.5, 2.5, array['Set the rope at about face height.', 'Take the ends of the rope with your thumbs towards you.', 'Step back until the cable is tight with your arms straight.'], array['Pull the rope towards your forehead, elbows high.', 'Pull the ends apart at the end of the pull.', 'Squeeze your shoulder blades together.'], array['Pulling down to your chest.', 'Leaning back to cheat the weight.', 'Using so much weight your shoulders roll forward.'], '', 'Rear delt fly', 25),
  ('assistedpull', 'Assisted pull-up', 'upper', 'Back', 'Machine', 'weight', array['Lats', 'Upper back', 'Biceps'], 6, 10, 5, 5, array['Set the assist weight, more weight means more help.', 'Kneel or stand on the pad and take a shoulder-width grip.', 'Start with your arms long and chest up.'], array['Pull your elbows down towards your ribs.', 'Get your chin over the bar.', 'Lower slowly until your arms are straight.'], array['Using momentum to swing up.', 'Cutting the range short at the bottom.', 'Shrugging your shoulders to your ears.'], '', 'Lat pulldown', 26),
  ('straightarm', 'Straight-arm pulldown', 'upper', 'Back', 'Cable', 'weight', array['Lats'], 8, 12, 2.5, 2.5, array['Set the pulley high with a bar or rope.', 'Stand a step back with a slight hinge at the hips.', 'Hold the bar at shoulder height with straight arms.'], array['Sweep the bar down to your thighs with straight arms.', 'Squeeze your lats at the bottom.', 'Let it rise slowly until your lats stretch.'], array['Bending your elbows into a triceps pushdown.', 'Rounding your back.', 'Using your body weight to drive it down.'], '', 'Lat pulldown', 27),
  ('dbrow', 'One-arm dumbbell row', 'upper', 'Back', 'Dumbbells', 'weight', array['Lats', 'Mid back', 'Biceps'], 8, 12, 2, 2, array['Put one hand and the same-side knee on a bench.', 'Hold a dumbbell in your free hand with your arm hanging straight.', 'Keep your back flat and parallel to the floor.'], array['Pull the dumbbell to your hip, elbow close to your body.', 'Pause and squeeze your back.', 'Lower until your arm is long again.'], array['Twisting your torso to lift.', 'Pulling towards your shoulder instead of your hip.', 'Letting your back round.'], '', 'Low seated row', 28),
  ('overheadtri', 'Overhead triceps extension', 'upper', 'Arms', 'Cable', 'weight', array['Triceps'], 8, 12, 2.5, 2.5, array['Set the pulley low and attach a rope.', 'Face away from the stack, holding the rope behind your head.', 'Take a staggered stance with your elbows pointing forward.'], array['Straighten your arms up and forward.', 'Keep your elbows close to your ears.', 'Lower until you feel a stretch behind your arms.'], array['Letting your elbows flare out wide.', 'Arching your lower back.', 'Using body momentum to push.'], '', 'Triceps pushdown', 29),
  ('dbcurl', 'Dumbbell curl', 'upper', 'Arms', 'Dumbbells', 'weight', array['Biceps'], 8, 12, 2, 2, array['Stand tall with a dumbbell in each hand, palms forward.', 'Keep your elbows tucked at your sides.', 'Stand with your feet hip-width apart.'], array['Curl the weights up towards your shoulders.', 'Squeeze your biceps at the top.', 'Lower slowly until your arms are straight.'], array['Swinging your body to lift.', 'Letting your elbows drift forward.', 'Dropping the weights fast.'], '', 'Hammer curl', 30),
  ('preacher', 'Preacher curl machine', 'upper', 'Arms', 'Machine', 'weight', array['Biceps'], 8, 12, 2.5, 2.5, array['Set the seat so your armpits rest on top of the pad.', 'Grip the handles with your arms extended.', 'Sit tall and keep your chest on the pad.'], array['Curl the handles up towards your shoulders.', 'Squeeze at the top.', 'Lower slowly until your arms are almost straight.'], array['Lifting your elbows off the pad.', 'Slamming into the bottom.', 'Leaning back to cheat the weight.'], '', 'Dumbbell curl', 31),
  ('tricepsdip', 'Triceps dip machine', 'upper', 'Arms', 'Machine', 'weight', array['Triceps', 'Chest'], 8, 12, 2.5, 2.5, array['Adjust the seat so the handles are at your lower ribs.', 'Sit tall with your back against the pad.', 'Grip the handles with your elbows tucked in.'], array['Press down until your arms are straight.', 'Keep your shoulders down and back.', 'Return slowly until your elbows are at 90 degrees.'], array['Shrugging your shoulders up.', 'Letting your elbows flare out.', 'Going too deep and pinching your shoulders.'], '', 'Triceps pushdown', 32),
  ('hacksquat', 'Hack squat', 'lower', 'Legs', 'Machine', 'weight', array['Quads', 'Glutes'], 8, 12, 5, 5, array['Step into the machine with your back and shoulders against the pads.', 'Place your feet shoulder-width apart, toes slightly out.', 'Release the safety handles.'], array['Lower until your thighs are about parallel.', 'Press through your whole foot.', 'Keep your back flat on the pad.'], array['Letting your heels lift off the plate.', 'Letting your knees cave in.', 'Locking your knees hard at the top.'], '', 'Seated leg press', 33),
  ('goblet', 'Goblet squat', 'lower', 'Legs', 'Dumbbells', 'weight', array['Quads', 'Glutes', 'Core'], 8, 12, 2, 2, array['Hold one dumbbell upright against your chest with both hands.', 'Stand with your feet slightly wider than your shoulders.', 'Point your toes out a little.'], array['Sit straight down between your knees.', 'Keep your chest tall and elbows inside your knees.', 'Drive up through your whole foot.'], array['Letting your heels rise.', 'Rounding your back at the bottom.', 'Letting your knees fall inwards.'], '', 'Seated leg press', 34),
  ('rdl', 'Dumbbell Romanian deadlift', 'lower', 'Legs', 'Dumbbells', 'weight', array['Hamstrings', 'Glutes', 'Lower back'], 8, 12, 2, 2, array['Stand tall holding a dumbbell in each hand in front of your thighs.', 'Soften your knees and keep your chest up.', 'Set your feet hip-width apart.'], array['Push your hips back and slide the weights down your legs.', 'Stop when you feel a stretch in your hamstrings.', 'Drive your hips forward to stand tall.'], array['Rounding your lower back.', 'Bending your knees into a squat.', 'Letting the weights drift away from your legs.'], '', 'Back extension', 35),
  ('lunge', 'Dumbbell lunge', 'lower', 'Legs', 'Dumbbells', 'weight', array['Quads', 'Glutes'], 8, 12, 2, 2, array['Stand tall with a dumbbell in each hand at your sides.', 'Take a big step forward.', 'Keep your torso upright and core tight.'], array['Lower until both knees are at about 90 degrees.', 'Keep your front knee over your ankle.', 'Push through the front heel to stand.'], array['Letting your front knee dive inwards.', 'Taking too short a step.', 'Leaning your whole body forward.'], '', 'Goblet squat', 36),
  ('abduct', 'Hip abduction machine', 'lower', 'Legs', 'Machine', 'weight', array['Glutes', 'Outer thighs'], 10, 15, 5, 5, array['Sit with your back flat against the pad.', 'Place your legs against the outer pads.', 'Set the starting width so you feel a small stretch.'], array['Press your legs apart in a smooth motion.', 'Pause when you reach the end.', 'Return slowly until the pads nearly touch.'], array['Using momentum to swing the pads.', 'Leaning forward to cheat.', 'Letting the weights slam together.'], '', 'Hip adduction machine', 37),
  ('adduct', 'Hip adduction machine', 'lower', 'Legs', 'Machine', 'weight', array['Inner thighs'], 10, 15, 5, 5, array['Sit with your back flat against the pad.', 'Place your legs against the inner pads.', 'Set the starting width so you feel a small stretch.'], array['Squeeze your legs together smoothly.', 'Pause when the pads meet.', 'Return slowly to the starting width.'], array['Using momentum.', 'Opening too wide and straining your hips.', 'Letting the weights slam back.'], '', 'Hip abduction machine', 38),
  ('standcalf', 'Standing calf raise', 'lower', 'Legs', 'Machine', 'weight', array['Calves'], 12, 15, 5, 5, array['Set the shoulder pads so you can stand tall.', 'Place the balls of your feet on the platform.', 'Keep your knees almost straight.'], array['Lift your heels as high as you can.', 'Pause at the top for a beat.', 'Lower slowly until you feel a stretch.'], array['Bouncing at the bottom.', 'Bending your knees to push.', 'Only doing a short range.'], '', 'Calf raise', 39),
  ('cablecrunch', 'Cable crunch', 'core', 'Core', 'Cable', 'weight', array['Abs'], 10, 15, 2.5, 2.5, array['Attach a rope to the high pulley and kneel facing the stack.', 'Hold the rope beside your head.', 'Sit your hips back over your heels.'], array['Curl your ribs towards your hips.', 'Breathe out as you crunch.', 'Return slowly until your back is long.'], array['Pulling with your arms.', 'Sitting back and bending at the hips.', 'Using too much weight and rocking.'], '', 'Dead bug', 40),
  ('kneeraise', 'Hanging knee raise', 'core', 'Core', 'Bodyweight', 'bodyweight', array['Abs', 'Hip flexors'], 8, 15, 2.5, 2.5, array['Hang from the bar with a shoulder-width grip.', 'Brace your core and keep your legs together.', 'Start with your legs straight down.'], array['Raise your knees towards your chest.', 'Curl your pelvis up at the top.', 'Lower slowly without swinging.'], array['Swinging your body.', 'Only lifting with your hip flexors.', 'Dropping your legs fast.'], '', 'Dead bug', 41),
  ('sideplank', 'Side plank', 'core', 'Core', 'Bodyweight', 'timed', array['Obliques', 'Core', 'Shoulders'], 20, 40, 5, 5, array['Lie on your side with your elbow under your shoulder.', 'Stack your feet or place one in front of the other.', 'Lift your hips so your body is one line.'], array['Press your forearm into the floor.', 'Keep your hips high and ribs down.', 'Breathe steadily.'], array['Letting your hips sag.', 'Rolling your chest forward.', 'Holding your breath.'], '', 'Knee side plank', 42),
  ('deadbug', 'Dead bug', 'core', 'Core', 'Bodyweight', 'bodyweight', array['Abs', 'Core'], 8, 12, 2.5, 2.5, array['Lie on your back with your arms up and knees over your hips.', 'Press your lower back gently into the floor.', 'Brace your core.'], array['Lower the opposite arm and leg together.', 'Keep your lower back pressed down.', 'Return and switch sides slowly.'], array['Letting your back arch off the floor.', 'Rushing the movement.', 'Holding your breath.'], '', 'Plank', 43),
  ('preachercurl', 'Preacher curl', 'upper', 'Arms', 'Bench', 'weight', array['Biceps'], 8, 12, 2.5, 2.5, array['Set the pad so your armpits rest on top of it.', 'Hold an EZ bar with a shoulder-width underhand grip.', 'Start with your arms almost straight and your chest on the pad.'], array['Curl the bar up towards your shoulders.', 'Squeeze your biceps at the top.', 'Lower slowly until your arms are almost straight.'], array['Lifting your elbows off the pad.', 'Dropping fast through the bottom of the rep.', 'Swinging your body to get the bar up.'], '', 'Dumbbell curl', 44),
  ('strcablecurl', 'Straight bar cable curl', 'upper', 'Arms', 'Cable', 'weight', array['Biceps'], 8, 12, 2.5, 2.5, array['Attach a straight bar to the low pulley.', 'Stand a step back with your feet hip-width apart.', 'Hold the bar with a shoulder-width underhand grip, elbows at your sides.'], array['Curl the bar up towards your chest.', 'Keep your elbows pinned to your sides.', 'Lower slowly so the cable stays tight.'], array['Swinging your hips to lift.', 'Letting your elbows drift forward.', 'Letting the stack slam at the bottom.'], '', 'Cable curl', 45),
  ('smithsquat', 'Smith machine squat', 'lower', 'Legs', 'Smith machine', 'weight', array['Quads', 'Glutes'], 8, 12, 5, 5, array['Set the bar at about shoulder height and step under it.', 'Place your feet slightly in front of the bar, shoulder-width apart.', 'Rotate the bar to unrack it and keep your chest tall.'], array['Sit down and back until your thighs are about parallel.', 'Keep your whole foot on the floor.', 'Drive up and rotate the bar back to rack when done.'], array['Placing your feet directly under the bar so your knees travel too far.', 'Letting your heels lift.', 'Rounding your lower back at the bottom.'], '', 'Goblet squat', 46),
  ('smithbench', 'Smith machine bench press', 'upper', 'Chest', 'Smith machine', 'weight', array['Chest', 'Shoulders', 'Triceps'], 8, 12, 2.5, 2.5, array['Slide a flat bench so the bar lands over your mid chest.', 'Lie back with your eyes under the bar and your feet planted.', 'Take a grip slightly wider than your shoulders and rotate the bar to unrack.'], array['Lower the bar to your mid chest under control.', 'Press straight up without locking out hard.', 'Keep your shoulder blades pinched back.'], array['Bouncing the bar off your chest.', 'Lifting your hips off the bench.', 'Setting the bench too far so the bar path pulls on your shoulders.'], '', 'Dumbbell bench press', 47),
  ('smithincline', 'Smith machine incline press', 'upper', 'Chest', 'Smith machine', 'weight', array['Upper chest', 'Shoulders', 'Triceps'], 8, 12, 2.5, 2.5, array['Set an incline bench at about 30 degrees under the bar.', 'Lie back with the bar over your upper chest.', 'Grip slightly wider than your shoulders and rotate the bar to unrack.'], array['Lower to your upper chest with your elbows at about 45 degrees.', 'Press straight up.', 'Keep your feet planted and your back flat on the pad.'], array['Flaring your elbows straight out.', 'Using too steep an incline so it becomes a shoulder press.', 'Letting your back arch off the bench.'], '', 'Incline dumbbell press', 48),
  ('smithshoulder', 'Smith machine shoulder press', 'upper', 'Shoulders', 'Smith machine', 'weight', array['Shoulders', 'Triceps'], 8, 12, 2.5, 2.5, array['Set an upright bench so the bar lines up with your face.', 'Sit tall and grip the bar a little wider than your shoulders.', 'Rotate the bar to unrack at about chin height.'], array['Press straight up until your arms are nearly straight.', 'Lower to your chin under control.', 'Keep your ribs down and your core tight.'], array['Arching your lower back.', 'Pressing the bar in front of your face so it drifts forward.', 'Lowering it only halfway.'], '', 'Dumbbell shoulder press', 49),
  ('smithrow', 'Smith machine bent-over row', 'upper', 'Back', 'Smith machine', 'weight', array['Lats', 'Mid back', 'Biceps'], 8, 12, 2.5, 2.5, array['Set the bar at about knee height.', 'Hinge at your hips with a flat back and an overhand grip.', 'Rotate the bar to unrack and let your arms hang.'], array['Pull the bar towards your lower ribs.', 'Squeeze your shoulder blades together at the top.', 'Lower slowly until your arms are straight.'], array['Standing up as you pull.', 'Rounding your back.', 'Yanking the bar with your arms instead of your back.'], '', 'One-arm dumbbell row', 50),
  ('smithrdl', 'Smith machine Romanian deadlift', 'lower', 'Legs', 'Smith machine', 'weight', array['Hamstrings', 'Glutes', 'Lower back'], 8, 12, 5, 5, array['Set the bar at about hip height.', 'Stand with your feet hip-width apart and an overhand grip, hands outside your thighs.', 'Rotate the bar to unrack and soften your knees.'], array['Push your hips back and slide the bar down your thighs.', 'Stop when you feel a hamstring stretch.', 'Drive your hips forward to stand tall.'], array['Rounding your lower back.', 'Bending your knees so it becomes a squat.', 'Letting the bar drift away from your legs.'], '', 'Dumbbell Romanian deadlift', 51),
  ('smithsplit', 'Smith machine split squat', 'lower', 'Legs', 'Smith machine', 'weight', array['Quads', 'Glutes'], 8, 12, 2.5, 2.5, array['Set the bar at about shoulder height and step under it.', 'Take a long step with your back foot behind you.', 'Rotate the bar to unrack and keep your chest tall.'], array['Lower straight down until your front thigh is about parallel.', 'Keep your front heel flat.', 'Push through your front foot to stand.'], array['Letting your front knee dive inwards.', 'Taking too short a stance.', 'Leaning your torso far forward.'], '', 'Dumbbell lunge', 52),
  ('smithcalf', 'Smith machine calf raise', 'lower', 'Legs', 'Smith machine', 'weight', array['Calves'], 12, 15, 5, 5, array['Place a plate or step under the bar''s line to stand on the balls of your feet.', 'Put the bar across your upper back.', 'Keep your knees almost straight.'], array['Rise up onto your toes as high as you can.', 'Pause at the top for a beat.', 'Lower slowly until you feel a stretch.'], array['Bouncing at the bottom.', 'Bending your knees to push.', 'Only doing a short range.'], '', 'Standing calf raise', 53),
  ('smithclose', 'Smith machine close-grip press', 'upper', 'Arms', 'Smith machine', 'weight', array['Triceps', 'Chest'], 8, 12, 2.5, 2.5, array['Slide a flat bench under the bar, over your lower chest.', 'Lie back and take a grip about shoulder-width.', 'Rotate the bar to unrack with your elbows tucked.'], array['Lower the bar to your lower chest with your elbows close to your sides.', 'Press straight up and squeeze your triceps.', 'Keep your wrists straight.'], array['Using a grip so narrow it strains your wrists.', 'Flaring your elbows out.', 'Bouncing the bar off your chest.'], '', 'Triceps pushdown', 54),
  ('chestrow', 'Chest-supported row', 'upper', 'Back', 'Dumbbells', 'weight', array['Mid back', 'Lats', 'Biceps'], 8, 12, 2, 2, array['Set an incline bench to about 30 degrees and lie chest-down on it.', 'Let the dumbbells hang straight down with your arms long.', 'Keep your head level with your spine and your feet planted.'], array['Pull your elbows back and up towards your hips.', 'Squeeze your shoulder blades together at the top.', 'Lower slowly until your arms are straight.'], array['Lifting your chest off the pad to swing the weight.', 'Shrugging your shoulders up.', 'Cutting the range short at the bottom.'], '', 'Low seated row', 55)
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, muscle_group = excluded.muscle_group, kit = excluded.kit,
  kind = excluded.kind, muscles = excluded.muscles, rep_lo = excluded.rep_lo, rep_hi = excluded.rep_hi,
  weight_step_kg = excluded.weight_step_kg, default_increment_kg = excluded.default_increment_kg,
  setup = excluded.setup, cues = excluded.cues, mistakes = excluded.mistakes, backup_name = excluded.backup_name,
  sort_order = excluded.sort_order;
